mapper.select:
SELECT id, conversation_id, username, summary_text, summarized_message_count,
       summary_version, create_time, update_time
FROM conversation_summary
WHERE conversation_id = #{conversationId}
  AND username = #{username}

mapper.update:
UPDATE conversation_summary
SET summary_text = #{summaryText},
    summarized_message_count = #{summarizedMessageCount},
    summary_version = summary_version + 1,
    update_time = NOW()
WHERE conversation_id = #{conversationId}
  AND username = #{username}
  AND summary_version = #{version}

mapper.delete:
DELETE FROM conversation_summary
WHERE conversation_id = #{conversationId}
  AND username = #{username}
